<?php declare(strict_types=1);
namespace FMonitor2\PilotHttp;

final class ProductionObjectCardRenderer implements ObjectCardRenderer,CompatibilityObjectCardRenderer
{
    public function render(HttpUser $user,array $c):string
    {
        $e=[PilotView::class,'e'];$id=$e($c['id']);$order=$c['order'];$date=static fn(mixed $value):string=>'<time datetime="'.$e($value).'">'.PilotView::date($value).'</time>';
        $notice=isset($c['flash'])&&$c['flash']?'<div class="fm2-alert" role="status">'.$e($c['flash']['message']).'</div>':'';
        [$command,$downloads]=$this->command($c,$id,$order);
        $dates=$this->panel('Сроки работ',PilotView::dl([['Плановое начало',$date($c['plannedStartDate'])],['Плановое окончание',$date($c['plannedFinishDate'])],['Фактическое начало',$c['actualStartDate']?$date($c['actualStartDate']):'Не зафиксировано']]));
        $docs=$this->panel('Распоряжение и 1С ДО',$order===null?'<div class="fm2-quiet-empty"><strong>Распоряжение не сформировано</strong><span>Документ появится после выбора монтажников.</span></div>':PilotView::dl([['Дата распоряжения',PilotView::date($order['orderDate'])],['Версия',$e($order['version'])],['Регистрация в 1С ДО',$e($order['registrationNumber']===null?'Ожидается':'№ '.$order['registrationNumber'])]]).$downloads);
        $engineer=$c['controlEngineer']??null;$engineerValue=$engineer===null?'Не назначен':$e($engineer['fullName']).' · '.$e($engineer['position']);$engineerForm='';if($c['canAssignEngineer']??false){$options='<option value="">Выберите пользователя</option>';foreach($c['engineers']as$x)$options.='<option value="'.$e($x['userId']).'"'.(($engineer['userId']??null)===$x['userId']?' selected':'').'>'.$e($x['fullName']).'</option>';$engineerForm='<form class="fm2-engineer-form" method="post" action="/pilot/objects/'.$id.'/control-engineer"><input type="hidden" name="csrfToken" value="'.$e($c['csrfToken']).'"><input type="hidden" name="processRevision" value="'.$e($c['processRevision']).'"><label class="shlz-field shlz-field--select"><span class="shlz-field__label">Инженер строительного контроля</span><span class="shlz-field__control"><select class="shlz-select" name="controlEngineerUserId" required>'.$options.'</select></span></label><button class="shlz-button shlz-button--primary" type="submit">Назначить</button><small>Доступны активные пользователи с ролью «Строительный контроль».</small></form>';}$teamRows=[['Инженер стройконтроля',$engineerValue]];if($order===null)$teamRows[]=['Монтажники','Ещё не назначены'];else foreach($order['installers']as$x)$teamRows[]=['Монтажник',$e($x['fullName']).' · таб. '.$e($x['tabId']).' · '.$e($x['position'])];$team=$this->panel('Команда объекта',PilotView::dl($teamRows).$engineerForm);
        $eventLabels=['assignment_order_prepared'=>'Распоряжение сформировано','assignment_order_registered'=>'Распоряжение зарегистрировано в 1С ДО','assignment_order_prepare_rejected'=>'Формирование распоряжения отклонено','installation_opened'=>'Монтажные работы открыты','control_engineer_changed'=>'Инженер стройконтроля изменён'];
        $history='<div class="fm2-event-list">';if($c['events']===[])$history.='<div class="fm2-quiet-empty"><strong>Событий пока нет</strong><span>Значимые действия появятся здесь автоматически.</span></div>';else foreach(\array_slice($c['events'],0,5)as$x)$history.='<div class="fm2-event"><time>'.$e($x['occurredAt']).'</time><div><strong>'.$e($x['label']??$eventLabels[$x['type']]??$x['type']).'</strong><small>Пользователь '.$e($x['actorId']).'</small></div></div>';$history.='</div>';$history=$this->panel('Последние события',$history);
        $problems=$this->panel('Проблемы',$order===null&&($c['controlEngineer']??null)===null?'<div class="fm2-problem"><strong>Не назначен инженер стройконтроля</strong><span>Назначьте инженера, чтобы сформировать распоряжение.</span></div>':'<div class="fm2-quiet-empty"><strong>Открытых проблем нет</strong><span>Блокирующие условия не обнаружены.</span></div>');
        $statusPaint=$c['opened']?'shlz-status--bright-green':'shlz-status--orange';$body='<header class="fm2-object-identity"><div><h1>Объект монтажа № '.$id.'</h1><p>'.$e($c['address']).', подъезд '.$e($c['entrance']).'</p><span>Регистрационный номер '.$e($c['registrationNumber']).'</span></div><span class="shlz-status '.$statusPaint.'">'.$e($c['status']).'</span></header>'.$notice.'<section class="fm2-next-action" aria-label="Ближайшее действие">'.$command.'</section><div class="fm2-object-dashboard"><main><div class="fm2-section-grid">'.$dates.$team.'</div>'.$docs.'</main><aside>'.$problems.$history.'</aside></div>';
        $field=$c['flash']['field']??null;if(\in_array($field,['registrationNumber','actualStartDate'],true)){$errorId=$field.'-error';$body=\str_replace('role="status"','role="status" id="'.$errorId.'"',$body);$body=\str_replace('name="'.$field.'"','name="'.$field.'" aria-invalid="true" aria-describedby="'.$errorId.'"',$body);}
        return PilotView::document($user,'Объект монтажа № '.$id,'Объекты монтажа',PilotView::breadcrumb([['Объекты монтажа','/pilot/objects']],'Объект монтажа № '.$id),$body);
    }

    private function command(array $c,string $id,?array $order):array
    {
        $e=[PilotView::class,'e'];$downloads='';
        if($order===null)return ['<div><h2>Сформируйте распоряжение</h2><p>'.(($c['controlEngineer']??null)===null?'Сначала назначьте инженера в карточке объекта, затем выберите монтажников.':'Инженер подтянется из карточки объекта, в распоряжении выберите монтажников.').'</p></div>'.((($c['canPrepare']??false)&&!($c['hasPtoAct']??false)&&($c['controlEngineer']??null)!==null)?'<a class="shlz-link" href="/pilot/objects/'.$id.'/assignment-order/prepare">Сформировать распоряжение</a>':''),''];
        $base='/pilot/objects/'.$id.'/assignment-orders/'.$e($order['version']);$downloads='<div class="shlz-document-list fm2-order-documents">';
        foreach($order['artifacts']??[] as $artifact){$type=$artifact['type']??null;$media=$artifact['mediaType']??null;if(!in_array($type,['order','appendix'],true))continue;$isPdf=$media==='application/pdf';$filename=$type==='order'&&$isPdf?'Распоряжение о закреплении монтажников.pdf':(string)($artifact['filename']??'Документ');$href=$base.'/artifacts/'.$e($type);$extension=$isPdf?'PDF':'HTML';$size=$this->fileSize((int)($artifact['size']??0));$modified=(new \DateTimeImmutable((string)$order['preparedAt']))->setTimezone(new \DateTimeZone('Europe/Moscow'))->format('d.m.Y, H:i');$visual=$isPdf?'<img src="/pilot/assets/icons/file-pdf-default.svg" alt="">':'';$downloads.='<div class="shlz-document-row" data-file-type="'.($isPdf?'pdf-default':'document').'"><span class="shlz-document-row__visual" aria-hidden="true">'.$visual.'</span><span class="shlz-document-row__content"><a class="shlz-document-row__title" href="'.$href.'" title="'.$e($filename).'"'.($isPdf?' target="_blank"':'').'>'.$e($filename).'</a><span class="shlz-document-row__meta">'.$extension.' · '.$e($size).' · Версия '.$e($order['version']).'</span><span class="shlz-document-row__modified">Сформирован '.$e($modified).'</span></span><span class="shlz-document-row__actions"><a class="shlz-document-row__action" href="'.$href.'" download="'.$e($filename).'" aria-label="Скачать '.$e($filename).'"><img src="/pilot/assets/icons/download.svg" alt=""></a></span></div>';}
        $downloads.='</div>';
        if(!$c['opened']&&$order['status']==='prepared'&&($c['canRegister']??false)){$form='<form class="fm2-inline-form fm2-registration-form" method="post" action="'.$base.'/registration">'.$this->hidden($c,$order).'<label for="registrationNumber">Номер распоряжения в 1С ДО</label><input id="registrationNumber" name="registrationNumber" maxlength="120" required><button class="shlz-button shlz-button--primary" type="submit">Сохранить номер</button></form>';return ['<div><h2>Внесите номер 1С ДО</h2><p>Документ уже сформирован: его можно открыть или скачать в разделе «Документы».</p></div>'.$form,$downloads];}
        if(!$c['opened']&&$order['status']==='registered'&&($c['canOpen']??false)){$form='<form class="fm2-inline-form" method="post" action="/pilot/objects/'.$id.'/open">'.$this->hidden($c,$order).'<label for="actualStartDate">Фактическая дата начала работ</label><input id="actualStartDate" type="date" name="actualStartDate" required><small>Не раньше даты распоряжения и не позже сегодняшней даты</small><button class="shlz-button shlz-button--primary" type="submit">Открыть работы</button></form>';return ['<div><h2>Откройте монтажные работы</h2><p>Распоряжение зарегистрировано.</p></div>'.$form,$downloads];}
        return ['<div><h2>Работы открыты</h2><p>Стройконтроль может фиксировать ход монтажа и фотоотчёт.</p></div><a class="fm2-primary-link" href="/pilot/objects/'.$id.'/checklist">Открыть чек-лист</a>',$downloads];
    }
    private function hidden(array $c,array $order):string{$e=[PilotView::class,'e'];return '<input type="hidden" name="csrfToken" value="'.$e($c['csrfToken']).'"><input type="hidden" name="processRevision" value="'.$e($c['processRevision']).'"><input type="hidden" name="assignmentOrderVersion" value="'.$e($order['version']).'">';}
    private function fileSize(int $bytes):string{if($bytes<1024)return $bytes.' Б';if($bytes<1048576)return number_format($bytes/1024,$bytes<10240?1:0,',','').' КБ';return number_format($bytes/1048576,1,',','').' МБ';}
    private function panel(string $title,string $content):string{return '<section class="fm2-panel"><h2>'.$title.'</h2>'.$content.'</section>';}
    public function renderCompatibility(HttpUser $user,array $c):string{return $this->render($user,$c);}
}
